INSERT [dbo].[ProductTemplate] ([Id], [CategoryId], [Name], [Description], [Price], [ThumbnailImage], [Image], [CollectionImage], [UrlPath], [CreatedTime], [LastestUpdatedTime], [InactiveTime], [IsActive], [AveDateForComplete], [Gender]) VALUES (N'0432e064-878f-428c-bb7d-d5ac90', N'e10cee9f-00aa-4fef-a89e-f6663f', N'tét', N'Áo kiểu cổ tròn dành cho nữ là trang phục cơ bản và tinh tế. Với thiết kế cổ tròn, ôm sát hoặc hơi rộng, áo thường làm từ cotton, thun hoặc lụa. Dễ phối đồ, áo này phù hợp nhiều hoàn cảnh từ công sở đến dạo phố, mang lại vẻ thanh lịch và thoải mái.', CAST(250000.000 AS Decimal(18, 3)), N'{"ObjectName":"Uploads/ProductTemplates/0432e064-878f-428c-bb7d-d5ac90/ThumnailImages/a6f7ff58-d3cd-470f-aaa7-e23698.jpg","ObjectUrl":"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2F0432e064-878f-428c-bb7d-d5ac90%2FThumnailImages%2Fa6f7ff58-d3cd-470f-aaa7-e23698.jpg?alt=media&token=3783481a-4ea8-4000-91cc-3081d98e2fb4"}', N'["{\"ObjectName\":\"Uploads/ProductTemplates/0432e064-878f-428c-bb7d-d5ac90/Images/8e574f30-0659-4a00-b6f8-01cebd.jpg\",\"ObjectUrl\":\"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2F0432e064-878f-428c-bb7d-d5ac90%2FImages%2F8e574f30-0659-4a00-b6f8-01cebd.jpg?alt=media&token=43c14ea4-c2ba-4b7c-98be-3b64ab28ea44\"}","{\"ObjectName\":\"Uploads/ProductTemplates/0432e064-878f-428c-bb7d-d5ac90/Images/c7dbf7dd-eadc-4d82-8f58-2f6a43.jpg\",\"ObjectUrl\":\"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2F0432e064-878f-428c-bb7d-d5ac90%2FImages%2Fc7dbf7dd-eadc-4d82-8f58-2f6a43.jpg?alt=media&token=08546284-11e5-4d7b-9079-0ea72cf897d7\"}","{\"ObjectName\":\"Uploads/ProductTemplates/0432e064-878f-428c-bb7d-d5ac90/Images/80517802-4303-4e6e-9533-c280a1.jpg\",\"ObjectUrl\":\"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2F0432e064-878f-428c-bb7d-d5ac