INSERT [dbo].[ProductTemplate] ([Id], [CategoryId], [Name], [Description], [Price], [ThumbnailImage], [Image], [CollectionImage], [UrlPath], [CreatedTime], [LastestUpdatedTime], [InactiveTime], [IsActive], [AveDateForComplete], [Gender]) VALUES (N'320efb16-5c3a-4cb8-9a22-8a289a', N'72d50e40-81b7-452d-84fa-298068', N'Áo đầm có cổ Polo', N'Áo đầm có cổ polo là sự kết hợp tinh tế giữa phong cách thể thao năng động và nét duyên dáng, nữ tính. Đặc trưng bởi cổ áo polo cổ điển, thường đi kèm với vài nút cài ở phần cổ, thiết kế này mang lại vẻ ngoài trẻ trung và thoải mái. Kiểu dáng của áo đầm polo đa dạng từ ôm sát để tôn lên dáng vóc, đến suông rộng cho cảm giác thoải mái tối đa. Màu sắc và họa tiết thường thấy bao gồm sắc thái trung tính như xanh navy, trắng, xám, hoặc những màu sắc tươi sáng và họa tiết sọc, kẻ ngang, hoa nhỏ, đem lại vẻ ngoài trẻ trung, năng động. Áo đầm polo phù hợp với nhiều hoàn cảnh, từ việc đi chơi, dạo phố cho đến những buổi picnic hay sự kiện ngoài trời, là lựa chọn lý tưởng cho những ai yêu thích sự kết hợp giữa thoải mái và phong cách.', CAST(300000.000 AS Decimal(18, 3)), N'{"ObjectName":"Uploads/ProductTemplates/320efb16-5c3a-4cb8-9a22-8a289a/ThumnailImages/93d0da08-e479-457a-91ab-f9b574.jpg","ObjectUrl":"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2F320efb16-5c3a-4cb8-9a22-8a289a%2FThumnailImages%2F93d0da08-e479-457a-91ab-f9b574.jpg?alt=media&token=4dc376ef-e869-45a4-b8e4-69b317229369"}', N'["{\"ObjectName\":\"Uploads/ProductTemplates/320efb16-5c3a-4cb8-9a22-8a289a/Images/c7849ca8-c53c-4a37-b8ba-613bc3.jpg\",\"ObjectUrl\":\"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2F320efb16-5c3a-4cb8-9a22-8a289a%2FImages%2Fc7849ca8-c53c-4a37-b8ba-613bc3.jpg?alt=media&token=361a6a7b-343d-4b4f-b27b-208b4d2bff2e\"}","{\"ObjectName\":\"Uploads/ProductTemplates/320efb16-5c3a-4cb8-9a22-8a289a/Images/dcf61b2b-dee8-490e-9be4-de13a6.jpg\",\"ObjectUrl\":