INSERT [dbo].[ProductTemplate] ([Id], [CategoryId], [Name], [Description], [Price], [ThumbnailImage], [Image], [CollectionImage], [UrlPath], [CreatedTime], [LastestUpdatedTime], [InactiveTime], [IsActive], [AveDateForComplete], [Gender]) VALUES (N'4f6885a2-9db1-49c9-964b-ec2ff3', N'97d686fb-0ca1-4441-be85-8fb7cd', N'Áo Vest Caro Slimfit Cổ Nhọn AV038 Màu Đen', N'Chiếc áo vest Caro Slimfit cổ nhọn AV038 màu đen là một thiết kế thời trang dành cho nam giới, được may từ chất liệu vải cao cấp với họa tiết caro tinh tế. Màu đen của áo mang đến vẻ ngoài lịch lãm và tinh tế, phù hợp với nhiều dịp sử dụng từ công sở đến các buổi tiệc tối. Áo có thiết kế slim fit, ôm sát cơ thể nhằm tôn lên dáng vẻ thon gọn, hiện đại của người mặc. Cổ áo nhọn đặc trưng tạo điểm nhấn ấn tượng, kết hợp cùng nút áo và các chi tiết khác được chăm chút tỉ mỉ, mang đến sự sang trọng và thanh lịch. Chiếc áo vest này có thể kết hợp cùng quần tây hoặc quần jeans để phù hợp với nhiều phong cách khác nhau.', CAST(1250000.000 AS Decimal(18, 3)), N'{"ObjectName":"Uploads/ProductTemplates/4f6885a2-9db1-49c9-964b-ec2ff3/ThumnailImages/6e077945-d18c-4b27-88a4-7a795c.jpg","ObjectUrl":"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2F4f6885a2-9db1-49c9-964b-ec2ff3%2FThumnailImages%2F6e077945-d18c-4b27-88a4-7a795c.jpg?alt=media&token=49e9ba5d-2649-41bf-bb39-474c2035f80b"}', N'["{\"ObjectName\":\"Uploads/ProductTemplates/4f6885a2-9db1-49c9-964b-ec2ff3/Images/4d6544fb-3934-4645-907c-1bbced.jpg\",\"ObjectUrl\":\"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2F4f6885a2-9db1-49c9-964b-ec2ff3%2FImages%2F4d6544fb-3934-4645-907c-1bbced.jpg?alt=media&token=88f95ccf-e695-4df2-8e9d-ae6fdb83e0a5\"}","{\"ObjectName\":\"Uploads/ProductTemplates/4f6885a2-9db1-49c9-964b-ec2ff3/Images/0e3123a9-8afb-4206-bfd1-6e8ff0.jpg\",\"ObjectUrl\":\"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProduc