INSERT [dbo].[ProductTemplate] ([Id], [CategoryId], [Name], [Description], [Price], [ThumbnailImage], [Image], [CollectionImage], [UrlPath], [CreatedTime], [LastestUpdatedTime], [InactiveTime], [IsActive], [AveDateForComplete], [Gender]) VALUES (N'55f8823d-5fd0-4348-9d07-6146bc', N'3225e787-9cb5-494f-bf03-e91c89', N'Áo dài cách tân nữ', N'Áo dài cách tân, với sự pha trộn tinh tế giữa truyền thống và hiện đại, là biểu tượng của vẻ đẹp phụ nữ Việt Nam, đồng thời thể hiện sự sáng tạo không ngừng trong nghệ thuật thời trang. Chiếc áo này giữ lại dáng vẻ thướt tha, uyển chuyển của áo dài truyền thống với phần cổ áo đứng thanh lịch, tà áo dài mượt mà, nhưng được cách tân bằng cách cắt xẻ táo bạo ở tà, làm cho chiếc áo trở nên linh hoạt và phóng khoáng hơn khi di chuyển. Màu sắc của áo dài cách tân này rực rỡ với tông màu hồng pastel nhẹ nhàng, đem lại cảm giác tươi mới và trẻ trung. Họa tiết được lựa chọn là những bông hoa sen - biểu tượng của sự thuần khiết và thanh cao, được thêu tỉ mỉ với màu vàng đồng, tạo nên điểm nhấn nổi bật trên nền vải mượt mà. Sự kết hợp giữa màu sắc và họa tiết không chỉ làm tôn vẻ đẹp ánh sáng của người phụ nữ mặc nó, mà còn gợi nhớ đến vẻ đẹp truyền thống, pha lẫn với hơi thở hiện đại, phản ánh sự tự tin và phóng khoáng của người phụ nữ Việt Nam trong xã hội ngày nay.', CAST(650000.000 AS Decimal(18, 3)), N'{"ObjectName":"Uploads/ProductTemplates/55f8823d-5fd0-4348-9d07-6146bc/ThumnailImages/be7e0a85-a32a-47b8-9624-9731ed.jpg","ObjectUrl":"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2F55f8823d-5fd0-4348-9d07-6146bc%2FThumnailImages%2Fbe7e0a85-a32a-47b8-9624-9731ed.jpg?alt=media&token=6c459334-c63c-4ee3-b0b5-e74d5f1138b5"}', N'["{\"ObjectName\":\"Uploads/ProductTemplates/55f8823d-5fd0-4348-9d07-6146bc/Images/1ae23e02-57e7-4b45-b803-05abfc.jpg\",\"ObjectUrl\":\"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2F55f8823d-5fd0-4348-9d07-6146bc