INSERT [dbo].[ProductTemplate] ([Id], [CategoryId], [Name], [Description], [Price], [ThumbnailImage], [Image], [CollectionImage], [UrlPath], [CreatedTime], [LastestUpdatedTime], [InactiveTime], [IsActive], [AveDateForComplete], [Gender]) VALUES (N'86f842b4-dcbc-410a-8f03-0a1b06', N'61444c75-73fa-44d5-876b-1d89ca', N'Áo sơ mi tay dài công sở', N'Chiếc áo sơ mi là sự kết hợp tinh tế giữa sự thoải mái và phong cách. May từ chất liệu cotton mềm mại, nó đem lại cảm giác mát mẻ và thoáng khí, phù hợp cho cả ngày làm việc lẫn những buổi gặp gỡ bè bạn. Màu trắng tinh khôi được chọn làm nền chính, trong khi đó, các họa tiết nhỏ xinh dưới dạng những bông hoa văn nhí màu xanh pastel nhẹ nhàng được phân bố đều trên toàn bộ bề mặt áo, thêm một chút nét dịu dàng và tươi mới. Điểm nhấn nằm ở cổ áo button-down kinh điển và tay áo dài có thể xắn lên tạo sự linh hoạt, phù hợp với mọi dáng vóc. Dù kết hợp với quần jeans cho một ngày casual hay layer cùng áo len và quần tây cho những dịp trang trọng, chiếc áo sơ mi này chắc chắn sẽ là một lựa chọn không thể thiếu, mang đến nét đẹp đa chiều và vô cùng thanh lịch.', CAST(200000.000 AS Decimal(18, 3)), N'{"ObjectName":"Uploads/ProductTemplates/86f842b4-dcbc-410a-8f03-0a1b06/ThumnailImages/64a7a9d2-b0a3-496c-97fe-5347e9.jpg","ObjectUrl":"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2F86f842b4-dcbc-410a-8f03-0a1b06%2FThumnailImages%2F64a7a9d2-b0a3-496c-97fe-5347e9.jpg?alt=media&token=82eecaa3-5592-4650-b469-cea47174f423"}', N'["{\"ObjectName\":\"Uploads/ProductTemplates/86f842b4-dcbc-410a-8f03-0a1b06/Images/781d0c88-d853-4aaa-88d7-6981db.jpg\",\"ObjectUrl\":\"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2F86f842b4-dcbc-410a-8f03-0a1b06%2FImages%2F781d0c88-d853-4aaa-88d7-6981db.jpg?alt=media&token=c550a4fc-d8fe-45f1-ac12-aae31001f7ca\"}","{\"ObjectName\":\"Uploads/ProductTemplates/86f842b4-dcbc-410a-8f03-0a1b06/Images/061a58a6-a66d-4e4