INSERT [dbo].[ProductTemplate] ([Id], [CategoryId], [Name], [Description], [Price], [ThumbnailImage], [Image], [CollectionImage], [UrlPath], [CreatedTime], [LastestUpdatedTime], [InactiveTime], [IsActive], [AveDateForComplete], [Gender]) VALUES (N'a57d8ca2-b2b2-4d79-858a-130b44', N'61444c75-73fa-44d5-876b-1d89ca', N'Áo sơ mi dài tay', N'Chiếc áo sơ mi là sự kết hợp tinh tế giữa sự thoải mái và phong cách. May từ chất liệu cotton mềm mại, nó đem lại cảm giác mát mẻ và thoáng khí, phù hợp cho cả ngày làm việc lẫn những buổi gặp gỡ bè bạn. Màu trắng tinh khôi được chọn làm nền chính, trong khi đó, các họa tiết nhỏ xinh dưới dạng những bông hoa văn nhí màu xanh pastel nhẹ nhàng được phân bố đều trên toàn bộ bề mặt áo, thêm một chút nét dịu dàng và tươi mới. Điểm nhấn nằm ở cổ áo button-down kinh điển và tay áo dài có thể xắn lên tạo sự linh hoạt, phù hợp với mọi dáng vóc. Dù kết hợp với quần jeans cho một ngày casual hay layer cùng áo len và quần tây cho những dịp trang trọng, chiếc áo sơ mi này chắc chắn sẽ là một lựa chọn không thể thiếu, mang đến nét đẹp đa chiều và vô cùng thanh lịch.', CAST(350000.000 AS Decimal(18, 3)), N'{"ObjectName":"Uploads/ProductTemplates/a57d8ca2-b2b2-4d79-858a-130b44/ThumnailImages/9aab1751-8476-4c6f-9741-c10d42.jpg","ObjectUrl":"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2Fa57d8ca2-b2b2-4d79-858a-130b44%2FThumnailImages%2F9aab1751-8476-4c6f-9741-c10d42.jpg?alt=media&token=b25ff4f0-3a73-4d64-ba25-afdc81770804"}', N'["{\"ObjectName\":\"Uploads/ProductTemplates/a57d8ca2-b2b2-4d79-858a-130b44/Images/faa021bb-cbc1-4188-a720-002f2d.jpg\",\"ObjectUrl\":\"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2Fa57d8ca2-b2b2-4d79-858a-130b44%2FImages%2Ffaa021bb-cbc1-4188-a720-002f2d.jpg?alt=media&token=92623da8-bcc7-415d-ab44-524bf61225f6\"}","{\"ObjectName\":\"Uploads/ProductTemplates/a57d8ca2-b2b2-4d79-858a-130b44/Images/a1a30878-3eac-4113-9045-e