INSERT [dbo].[ProductTemplate] ([Id], [CategoryId], [Name], [Description], [Price], [ThumbnailImage], [Image], [CollectionImage], [UrlPath], [CreatedTime], [LastestUpdatedTime], [InactiveTime], [IsActive], [AveDateForComplete], [Gender]) VALUES (N'ec6e1f75-3f05-48d6-b243-bb06f3', N'e8ae497b-7b87-4587-9865-e89514', N'Áo Vest Caro Slimfit Cổ Nhọn AV038 Màu Đen', N'Chiếc áo vest Caro Slimfit cổ nhọn AV038 màu đen là một thiết kế thời trang dành cho nam giới, được may từ chất liệu vải cao cấp với họa tiết caro tinh tế. Màu đen của áo mang đến vẻ ngoài lịch lãm và tinh tế, phù hợp với nhiều dịp sử dụng từ công sở đến các buổi tiệc tối. Áo có thiết kế slim fit, ôm sát cơ thể nhằm tôn lên dáng vẻ thon gọn, hiện đại của người mặc. Cổ áo nhọn đặc trưng tạo điểm nhấn ấn tượng, kết hợp cùng nút áo và các chi tiết khác được chăm chút tỉ mỉ, mang đến sự sang trọng và thanh lịch. Chiếc áo vest này có thể kết hợp cùng quần tây hoặc quần jeans để phù hợp với nhiều phong cách khác nhau.', CAST(1000000.000 AS Decimal(18, 3)), N'{"ObjectName":"Uploads/ProductTemplates/ec6e1f75-3f05-48d6-b243-bb06f3/ThumnailImages/b646813c-488f-41bd-979d-c11fab.jpg","ObjectUrl":"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2Fec6e1f75-3f05-48d6-b243-bb06f3%2FThumnailImages%2Fb646813c-488f-41bd-979d-c11fab.jpg?alt=media&token=34890ef8-2e58-4ace-937d-6870bab9405f"}', N'["{\"ObjectName\":\"Uploads/ProductTemplates/ec6e1f75-3f05-48d6-b243-bb06f3/Images/d41ff374-caae-469e-82fc-99e834.jpg\",\"ObjectUrl\":\"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2Fec6e1f75-3f05-48d6-b243-bb06f3%2FImages%2Fd41ff374-caae-469e-82fc-99e834.jpg?alt=media&token=6dd55c84-e037-43af-a7b6-ed6ab6745d09\"}","{\"ObjectName\":\"Uploads/ProductTemplates/ec6e1f75-3f05-48d6-b243-bb06f3/Images/fa8d2f41-de85-4f8b-9e79-24fb64.jpg\",\"ObjectUrl\":\"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProduc