INSERT [dbo].[ProductTemplate] ([Id], [CategoryId], [Name], [Description], [Price], [ThumbnailImage], [Image], [CollectionImage], [UrlPath], [CreatedTime], [LastestUpdatedTime], [InactiveTime], [IsActive], [AveDateForComplete], [Gender]) VALUES (N'fb43a27c-ea82-4d18-b8f6-2ece25', N'97d686fb-0ca1-4441-be85-8fb7cd', N'Áo Vest Caro Slimfit Cổ Nhọn AV038 Màu Đen', N'Chiếc áo vest Caro Slimfit cổ nhọn AV038 màu đen là một thiết kế thời trang dành cho nam giới, được may từ chất liệu vải cao cấp với họa tiết caro tinh tế. Màu đen của áo mang đến vẻ ngoài lịch lãm và tinh tế, phù hợp với nhiều dịp sử dụng từ công sở đến các buổi tiệc tối. Áo có thiết kế slim fit, ôm sát cơ thể nhằm tôn lên dáng vẻ thon gọn, hiện đại của người mặc. Cổ áo nhọn đặc trưng tạo điểm nhấn ấn tượng, kết hợp cùng nút áo và các chi tiết khác được chăm chút tỉ mỉ, mang đến sự sang trọng và thanh lịch. Chiếc áo vest này có thể kết hợp cùng quần tây hoặc quần jeans để phù hợp với nhiều phong cách khác nhau.', CAST(1250000.000 AS Decimal(18, 3)), N'{"ObjectName":"Uploads/ProductTemplates/fb43a27c-ea82-4d18-b8f6-2ece25/ThumnailImages/ae4c6689-7187-4da5-906e-e07cbe.jpg","ObjectUrl":"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2Ffb43a27c-ea82-4d18-b8f6-2ece25%2FThumnailImages%2Fae4c6689-7187-4da5-906e-e07cbe.jpg?alt=media&token=4f993574-bc77-4d5d-a6de-c0cb2ca7ec95"}', N'["{\"ObjectName\":\"Uploads/ProductTemplates/fb43a27c-ea82-4d18-b8f6-2ece25/Images/76de804f-43e3-445c-84c3-c4b3aa.jpg\",\"ObjectUrl\":\"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProductTemplates%2Ffb43a27c-ea82-4d18-b8f6-2ece25%2FImages%2F76de804f-43e3-445c-84c3-c4b3aa.jpg?alt=media&token=5654aa78-5291-48bb-a002-98b9e9e87711\"}","{\"ObjectName\":\"Uploads/ProductTemplates/fb43a27c-ea82-4d18-b8f6-2ece25/Images/16113711-4766-482f-9c93-14a7ec.jpg\",\"ObjectUrl\":\"https://firebasestorage.googleapis.com/v0/b/etailor-21a50.appspot.com/o/Uploads%2FProduc