/****** Object:  StoredProcedure [dbo].[GetOrderChat]    Script Date: 6/10/2024 9:39:56 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[GetOrderChat]
    @OrderId NVARCHAR(30)
AS

BEGIN
    SELECT TOP 1 
    [C].*
    FROM Chat C INNER JOIN [Order] O ON C.OrderId = O.Id
    WHERE O.Id = @OrderId
    AND O.[Status] >= 0
    AND O.[Status] <= 8
    AND O.IsActive = 1
    AND C.IsActive = 1
END;
GO
/****** Object:  StoredProcedure [dbo].[GetOrderChatList]    Script Date: 6/10/2024 9:39:56 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[GetOrderChatList]
    @OrderId NVARCHAR(30),
    @Role INT
AS

BEGIN
IF(@Role = 3)
BEGIN
    UPDATE ChatList
    SET IsRead = 1
    FROM ChatList CL
    INNER JOIN (
        SELECT C.Id
        FROM  [Chat] C
        INNER JOIN [dbo].[Order] O ON C.OrderId = O.Id
        WHERE O.Id = @OrderId
        AND O.[Status] >= 0 AND O.[Status] <= 8
        AND O.IsActive = 1
        AND C.IsActive = 1
    ) AS C ON C.Id = CL.ChatId
    WHERE CL.FromCus = 1;
END
ELSE
BEGIN
    UPDATE ChatList
    SET IsRead = 1
    FROM ChatList CL
    INNER JOIN (
        SELECT C.Id
        FROM  [Chat] C
        INNER JOIN [dbo].[Order] O ON C.OrderId = O.Id
        WHERE O.Id = @OrderId
        AND O.[Status] >= 0 AND O.[Status] <= 8
        AND O.IsActive = 1
        AND C.IsActive = 1
    ) AS C ON C.Id = CL.ChatId
    WHERE CL.FromCus = 0;
END
    SELECT [CL].*
    FROM [ChatList] CL INNER JOIN (
        SELECT TOP 1 C.Id
        FROM Chat C INNER JOIN (
            SELECT TOP 1 Id FROM [dbo].[Order]
            WHERE Id = @OrderId AND [Status] >= 0 AND [Status] <= 8 AND IsActive = 1
        ) AS O ON C.OrderId = O.Id
        WHERE C.IsActive = 1
    ) AS C ON C.Id = CL.ChatId
    WHERE CL.IsActive = 1
    ORDER BY CL.SendTime ASC
END;
GO
/****** Object:  StoredProcedure [dbo].[GetOrderDashboard]    Script Date: 6/10/2024 9:39:56 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[GetOrderDashboard]
    @StartDate DATETIME
AS
BEGIN
Select 
    [Status],
    COUNT(Id) As Total,
    SUM(CASE 
            WHEN AfterDiscountPrice IS NOT NULL THEN AfterDiscountPrice 
            ELSE TotalPrice 
        END) AS TotalPrice
FROM 
    [Order]
WHERE 
    IsActive = 1 
    AND MONTH(CreatedTime) = MONTH(@StartDate) 
    AND YEAR(CreatedTime) = YEAR(@StartDate)
GROUP BY 
    [Status];
END;
GO
/****** Object:  StoredProcedure [dbo].[GetOrderMaterials]    Script Date: 6/10/2024 9:39:56 AM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[GetOrderMaterials]
    @OrderId NVARCHAR(30)
AS
BEGIN
SELECT 
[OM].*
FROM OrderMaterial OM INNER JOIN (
    SELECT Id
    FROM [Order]
    WHERE Id = @OrderId AND [Status] > 0
) AS O ON OM.OrderId = O.Id
WHERE IsActive = 1
END;
